// Static native sampling in the shared workbench; not evidence of real playback.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Profiling;using Newtonsoft.Json;
public static class BlueWispVisualQA {
 const string Root="Assets/PixelFX/BlueWisp/V3/";
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/BlueWisp/V3");
 static List<object> samples=new List<object>();
 static Texture2D Render(float time,string name,string background="gray",string mute=null,string recolor=null,bool colorOnly=false,float yaw=0){
  GameObject clone=null,cg=null;RenderTexture rt=null;var old=RenderTexture.active;var mats=new List<Material>();
  try{
   clone=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/VFX_BlueWisp_V3_Loop.prefab"));clone.name="BlueWisp_QA_Temporary";clone.hideFlags=HideFlags.DontSave;foreach(var t in clone.GetComponentsInChildren<Transform>())t.gameObject.layer=31;
   foreach(var r in clone.GetComponentsInChildren<ParticleSystemRenderer>()){var m=new Material(r.sharedMaterial);mats.Add(m);r.sharedMaterial=m;if(mute!=null){var c=m.GetColor(mute);c.a=0;m.SetColor(mute,c);}if(recolor!=null)m.SetColor(recolor,new Color(1,.12f,.25f,1));if(colorOnly&&m.GetFloat("_LightOnly")>.5)r.enabled=false;}
   cg=new GameObject("BlueWisp_QA_Camera"){hideFlags=HideFlags.DontSave};var cam=cg.AddComponent<Camera>();cam.enabled=false;cam.orthographic=true;cam.orthographicSize=2.5f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=background=="light"?new Color(.88f,.91f,.93f):background=="dark"?new Color(.043f,.082f,.137f):new Color(69/255f,69/255f,69/255f);cam.cullingMask=1<<31;cam.allowHDR=false;cam.allowMSAA=false;cam.nearClipPlane=.05f;cam.farClipPlane=100;cam.transform.position=Quaternion.Euler(0,yaw,0)*new Vector3(0,0,-10);cam.transform.LookAt(Vector3.zero);
   foreach(var p in clone.GetComponentsInChildren<ParticleSystem>()){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.Simulate(0,false,true,false);for(float elapsed=0;elapsed<time;elapsed+=.001f)p.Simulate(Mathf.Min(.001f,time-elapsed),false,false,false);}
   rt=new RenderTexture(600,500,24,RenderTextureFormat.ARGB32);rt.Create();cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var image=new Texture2D(600,500,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,600,500),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Out,name+".png"),image.EncodeToPNG());
   var pixels=image.GetPixels32();var bg=pixels[0];int visible=pixels.Count(c=>Math.Abs(c.r-bg.r)+Math.Abs(c.g-bg.g)+Math.Abs(c.b-bg.b)>24);
   var p0=clone.GetComponent<ParticleSystem>();var parts=new ParticleSystem.Particle[2];var n=p0.GetParticles(parts);var baked=new Mesh();p0.GetComponent<ParticleSystemRenderer>().BakeMesh(baked,cam,ParticleSystemBakeMeshOptions.BakeRotationAndScale);var uv0=new List<Vector4>();var uv1=new List<Vector4>();baked.GetUVs(0,uv0);baked.GetUVs(1,uv1);
   samples.Add(new{name,time,background,mute,recolor,colorOnly,yaw,visible,age=n>0?parts[0].startLifetime-parts[0].remainingLifetime:-1,particles=clone.GetComponentsInChildren<ParticleSystem>().Sum(p=>p.particleCount),bakedUV0=uv0.Take(2).Select(x=>new[]{x.x,x.y,x.z,x.w}),bakedUV1=uv1.Take(2).Select(x=>new[]{x.x,x.y,x.z,x.w})});UnityEngine.Object.DestroyImmediate(baked);return image;
  }finally{RenderTexture.active=old;if(rt!=null){rt.Release();UnityEngine.Object.DestroyImmediate(rt);}if(clone!=null)UnityEngine.Object.DestroyImmediate(clone);if(cg!=null)UnityEngine.Object.DestroyImmediate(cg);foreach(var m in mats)UnityEngine.Object.DestroyImmediate(m);}
 }
 static int Diff(Texture2D a,Texture2D b){var x=a.GetPixels32();var y=b.GetPixels32();return Enumerable.Range(0,x.Length).Count(i=>Math.Abs(x[i].r-y[i].r)+Math.Abs(x[i].g-y[i].g)+Math.Abs(x[i].b-y[i].b)>10);}
 public static string Run(){
  if(Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||Application.isPlaying||SceneManager.GetActiveScene().path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong scope/state");Directory.CreateDirectory(Out);var scene=SceneManager.GetActiveScene();bool dirty=scene.isDirty;
  if(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None).Any(t=>t.gameObject.scene==scene&&t.gameObject.layer==31))throw new Exception("QA layer already in use.");
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/VFX_BlueWisp_V3_Loop.prefab");var shader=AssetDatabase.LoadAssetAtPath<Shader>(Root+"Shaders/BlueWispNative.shader");var components=prefab.GetComponentsInChildren<Component>(true).Select(c=>c==null?"MISSING":c.GetType().Name).Distinct().ToArray();if(components.Any(c=>c!="Transform"&&c!="ParticleSystem"&&c!="ParticleSystemRenderer"))throw new Exception("Unexpected prefab component");
  for(int i=0;i<4;i++)UnityEngine.Object.DestroyImmediate(Render(i*.07f+.035f,"Pose"+(i+1)));UnityEngine.Object.DestroyImmediate(Render(.315f,"LoopRepeat"));
  foreach(var bg in new[]{"light","dark"})UnityEngine.Object.DestroyImmediate(Render(.175f,"Background_"+bg,bg));
  UnityEngine.Object.DestroyImmediate(Render(.105f,"ColorOnly","gray",null,null,true));UnityEngine.Object.DestroyImmediate(Render(.105f,"Angle45","gray",null,null,false,45));
  var tests=new List<object>();foreach(var prop in new[]{"_Edge","_Blue","_Cyan","_Pale","_Core"}){var baseline=Render(.035f,"Palette_Default"+prop);var muted=Render(.035f,"Palette_Mute"+prop,"gray",prop);var red=Render(.035f,"Palette_Red"+prop,"gray",null,prop);int off=Diff(baseline,muted),recolor=Diff(baseline,red);tests.Add(new{prop,mutedPixels=off,recoloredPixels=recolor});if(off==0||recolor==0)throw new Exception("Palette endpoint inactive: "+prop);UnityEngine.Object.DestroyImmediate(baseline);UnityEngine.Object.DestroyImmediate(muted);UnityEngine.Object.DestroyImmediate(red);}
  var report=new{success=!ShaderUtil.ShaderHasError(shader),method="Edit Mode Simulate: deterministic static review, not real playback",components,systems=prefab.GetComponentsInChildren<ParticleSystem>().Select(p=>new{p.name,duration=p.main.duration,lifetime=p.main.startLifetime.constant,loop=p.main.loop,sheet=p.textureSheetAnimation.enabled,lights=p.lights.enabled,align=p.GetComponent<ParticleSystemRenderer>().alignment.ToString()}),shaderSupported=shader.isSupported,shaderMessages=ShaderUtil.GetShaderMessages(shader),tests,samples,sceneWasDirty=dirty,sceneIsDirty=scene.isDirty,resourceMemory=new{meshBytes=AssetDatabase.FindAssets("t:Mesh",new[]{Root.TrimEnd('/')}).Sum(id=>Profiler.GetRuntimeMemorySizeLong(AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(id)))),materialBytes=AssetDatabase.FindAssets("t:Material",new[]{Root.TrimEnd('/')}).Sum(id=>Profiler.GetRuntimeMemorySizeLong(AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(id))))}};
  File.WriteAllText(Path.Combine(Out,"VisualAndStructure.json"),JsonConvert.SerializeObject(report,Formatting.Indented));return JsonConvert.SerializeObject(new{report.success,report.components,report.tests,report.resourceMemory,samples=samples.Count,report.sceneIsDirty});
 }
}
